    input=input||{};var first=Math.floor(rnNumber(input.start,0,0,study.duration)),last=Math.floor(rnNumber(input.end,study.duration,0,study.duration)),start=Math.min(first,last),end=Math.max(first,last),a=study.rows[start],b=study.rows[end],duration=end-start,energy={},storage=study.id==='storage';
