    var firstNodes=rnEnergyPathway(a.run).nodes,lastNodes=rnEnergyPathway(b.run).nodes;
    var components=firstNodes.map(function(node,i){var endValue=lastNodes[i].value,delta=endValue-node.value;if(Math.abs(delta)<=Math.max(Math.abs(node.value),Math.abs(endValue))*1e-12)delta=0;return {id:node.id,component:node.component,label:node.label,unit:node.unit,start:node.value,end:endValue,delta:delta,deltaUnit:node.unit==='%'?'percentage points':node.unit};});
    var states=[],clippedMinutes=0,shortfallMinutes=0;
    for(var minute=start;minute<end;minute++){var row=study.rows[minute],state=states.find(function(state){return state.status===row.run.status;});if(!state){state={status:row.run.status,minutes:0,delivered:0};states.push(state);}state.minutes++;state.delivered+=row.run.power/60;energy.input+=row.run.available/60;energy.delivered+=row.run.power/60;energy.remainder+=storage?row.run.available/60*(1-row.run.extra.eta)+row.run.power/60/row.run.extra.eta-row.run.power/60:row.run.loss/60;if(storage&&row.run.extra.mode==='discharge'){energy.requested+=row.requested/60;energy.unserved+=row.unserved/60;}if(row.clipped)clippedMinutes++;if(row.unserved>1e-7)shortfallMinutes++;}
    return {version:1,id:study.id,profileId:study.profileId,label:study.label,baseSettings:Object.assign({},study.baseSettings),start:start,end:end,duration:duration,empty:duration===0,energy:energy,averagePower:duration?energy.delivered/(duration/60):null,components:components,startStatus:a.run.status,endStatus:b.run.status,startStored:storage?a.run.extra.stored:null,endStored:storage?b.run.extra.stored:null,states:states,clippedMinutes:clippedMinutes,shortfallMinutes:shortfallMinutes};
